"""Build static approval pages only; never writes application files or edits image pixels."""
from pathlib import Path
import json
import re
import shutil

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
snapshot = json.loads((HERE / 'source-snapshot.json').read_text(encoding='utf-8'))
context = HERE / 'context'
context.mkdir(exist_ok=True)
css_source = ROOT / 'public_html/option-a/assets/index-BT1Uhotc.css'
css = css_source.read_text(encoding='utf-8')
for relative in re.findall(r'url\([\'"]?([^\)\'" ]+)', css):
    if relative.startswith(('data:', 'http:', 'https:')):
        continue
    source = css_source.parent / relative
    if source.is_file():
        destination = context / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
(context / 'template-a.css').write_text(css, encoding='utf-8')
header = snapshot['header']
for logo in snapshot['logos']:
    source = ROOT / logo['url'].split(':3021/', 1)[1]
    shutil.copyfile(source, context / source.name)
    header = header.replace(logo['src'], './context/' + source.name)
hero = re.sub(r'<img\b[^>]*>', '<picture class="review-picture"><source media="(min-width:1024px)" srcset="a-h01-residential-woman-desktop-v1.png"><source media="(min-width:768px)" srcset="a-h01-residential-woman-medium-v3.png"><img class="review-photo" src="a-h01-residential-woman-mobile-v2.png" alt="Illustrative AI-generated scene of a woman laughing while using a laptop at home"></picture>', snapshot['hero'], count=1)
hero = hero.replace('<div class="absolute inset-0 bg-gradient-to-r from-black/75 via-black/40 to-transparent"></div>', '<div class="review-scrim" aria-hidden="true"></div>')
preview = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A-H 01 · Static composition review</title><link rel="stylesheet" href="context/template-a.css"><style>
html{overflow-y:scroll}body{margin:0} .review-picture{position:absolute;inset:0;display:block}.review-photo{width:100%;height:100%;object-fit:cover;object-position:100% 0;display:block}.review-scrim{position:absolute;inset:0;background:linear-gradient(90deg,rgba(29,29,31,.46),rgba(29,29,31,.44) 45%,transparent 75%)}
.review-note{padding:24px;background:#f5f5f7;color:#52525b;font:14px/1.6 Inter,system-ui,sans-serif;text-align:center}.review-note a{color:#a80710;text-decoration:underline}.review-original{display:none;background:#1d1d1f}.review-original img{width:100%;height:auto;display:block}.original-mode .ik-site{display:none}.original-mode .review-original{display:block}.no-overlay .review-scrim{display:none}.hide-copy #home-hero>.ik-container{visibility:hidden}
@media(max-width:1023px){.review-scrim{background:linear-gradient(0deg,rgba(29,29,31,.52),rgba(29,29,31,.10) 60%,transparent 82%)}}
@media(min-width:768px) and (max-width:1023px){#home-hero{background:#1d1d1f}.review-picture{inset:0 0 auto auto;width:66%;height:auto;aspect-ratio:4/3;mask-image:linear-gradient(90deg,transparent,#000 18%),linear-gradient(180deg,#000 70%,transparent);mask-composite:intersect}.review-photo{object-fit:contain;object-position:100% 0}}
@media(max-width:767px){.review-photo{object-position:50% 0}.review-scrim{background:linear-gradient(0deg,rgba(29,29,31,.60),rgba(29,29,31,.22) 58%,transparent 82%)}.proposal #home-hero{display:block;min-height:0;background:#1d1d1f}.proposal #home-hero:before{content:"";display:block;height:340px}.proposal .review-picture{height:340px;bottom:auto}.proposal .review-photo{object-position:50% 0}.proposal .review-scrim{height:340px;bottom:auto;background:linear-gradient(0deg,#1d1d1f,rgba(29,29,31,.12) 22%,transparent 42%)}.proposal #home-hero>.ik-container{padding-top:24px;padding-bottom:48px}}
</style></head><body class="BODYCLASS"><div class="ik-site" data-template="a">HEADER<main>HERO</main><aside class="review-note" id="review-note">A-H 01 · Static review only · Existing layout and copy · <a href="index.html">Back to approval review</a></aside></div><div class="review-original"><img id="original-image" alt="Original A-H 01 photographic candidate"></div><script>
const query=new URLSearchParams(location.search);const mode=query.get('mode')||'current';document.body.classList.toggle('hide-copy',query.get('hide-copy')==='1');document.body.classList.toggle('proposal',mode==='proposal');document.body.classList.toggle('no-overlay',query.get('overlay')==='none');document.body.classList.toggle('original-mode',mode==='original');const assets={desktop:'a-h01-residential-woman-desktop-v1.png',medium:'a-h01-residential-woman-medium-v3.png',mobile:'a-h01-residential-woman-mobile-v2.png'};document.querySelector('#original-image').src=assets[query.get('asset')]||assets.desktop;document.querySelector('#review-note').firstChild.textContent=mode==='proposal'?'A-H 01 · PROPOSED mobile image-above-copy layout · Not installed · ':'A-H 01 · Existing copy placement · Static review only · ';document.querySelectorAll('.ik-header button').forEach(b=>b.disabled=true);document.querySelector('#hero-check-coverage').addEventListener('click',()=>location.href='../../../public_html/option-a/#/coverage');document.querySelector('#hero-explore-plans').addEventListener('click',()=>location.href='../../../public_html/option-a/#/residential/plans');
</script></body></html>'''
preview = preview.replace('BODYCLASS', snapshot['bodyClass']).replace('HEADER', header).replace('HERO', hero)
(HERE / 'hero-preview.html').write_text(preview, encoding='utf-8')

